import SwiftUI
import RxSwift

final class ShowDetailsPresenter: ObservableObject {

    // MARK: - Public properties -
    
    @Published var showProgressHUD = false
    @Published var showDetailsError = false
    @Published var show: Show?
    @Published var reviews: [Review]?

    // MARK: - Private properties -

    private let interactor: ShowDetailsInteractorInterface
    private let wireframe: ShowDetailsWireframeInterface
    private let disposeBag = DisposeBag()

    private let showId: String

    // MARK: - Lifecycle -

    init(
        interactor: ShowDetailsInteractorInterface,
        wireframe: ShowDetailsWireframeInterface,
        showId: String
    ) {
        self.interactor = interactor
        self.wireframe = wireframe
        self.showId = showId
        
        bindPresenter()
    }
}

private extension ShowDetailsPresenter {
    
    func bindPresenter() {
        handleInitialLoad()
    }
    
    func handleInitialLoad() {
        
        showProgressHUD = true
        
        return Single.zip(
            interactor.getShowDetails(for: showId),
            interactor.getAllReviews(for: showId)
        )
        .subscribe(
            onSuccess: { [unowned self] show, reviews in
                showProgressHUD = false
                self.show = show
                self.reviews = reviews
            },
            onFailure: { [unowned self] error in
                showProgressHUD = false
                
            }
        )
        .disposed(by: disposeBag)
    }
}
